171	// ---------------------------------------------------------------------------
172	// Windows-only registry helpers
173	// ---------------------------------------------------------------------------
174	
175	#[cfg(windows)]
176	use windows::{
177	    core::PCWSTR,
178	    Win32::{
179	        Foundation::WIN32_ERROR,
180	        System::Registry::{
181	            RegCloseKey, RegEnumKeyExW, RegOpenKeyExW, RegQueryValueExW, HKEY, HKEY_USERS,
182	            KEY_READ, REG_EXPAND_SZ, REG_SZ, REG_VALUE_TYPE,
183	        },
184	    },
185	};
186	
187	/// RAII guard that calls `RegCloseKey` when dropped.
188	#[cfg(windows)]
189	struct RegKey(HKEY);
190	
191	#[cfg(windows)]
192	impl Drop for RegKey {
193	    fn drop(&mut self) {
194	        // SAFETY: HKEY came from a successful RegOpenKeyExW; RegCloseKey is
195	        // safe on any valid owned HKEY.
196	        unsafe {
197	            let _ = RegCloseKey(self.0);
198	        }
199	    }
200	}
201	
202	/// Opens `HKEY_USERS\{sid}\{subkey}` for read access.
203	///
204	/// Returns `None` and logs a WARN when the key does not exist or cannot be
205	/// opened.
206	#[cfg(windows)]
207	fn open_user_key(sid: &str, subkey: &str) -> Option<RegKey> {
208	    let path = format!(r"{}\{}", sid, subkey);
209	    let wide: Vec<u16> = path.encode_utf16().chain(std::iter::once(0)).collect();
210	    let mut hkey = HKEY::default();
211	    let status = unsafe {
212	        RegOpenKeyExW(
213	            HKEY_USERS,
214	            PCWSTR::from_raw(wide.as_ptr()),
215	            Some(0),
216	            KEY_READ,
217	            &mut hkey,
218	        )
219	    };
220	    if status.is_err() {
221	        tracing::warn!(
222	            provider_path = %path,
223	            error_code = status.0,
224	            "cloud enforcer: registry key not found or inaccessible"
225	        );
226	        return None;
227	    }
228	    Some(RegKey(hkey))
229	}
230	
231	/// Reads a `REG_SZ` or `REG_EXPAND_SZ` string value from an open `HKEY`.
232	///
233	/// Returns `None` and logs WARN on any failure.
234	#[cfg(windows)]
235	fn read_reg_string(hkey: HKEY, value_name: &str) -> Option<String> {
236	    let name_wide: Vec<u16> = value_name
237	        .encode_utf16()
238	        .chain(std::iter::once(0))
239	        .collect();
240	
241	    // First call: query required buffer size.
242	    let mut data_size = 0u32;
243	    let mut value_type = REG_VALUE_TYPE::default();
244	    let size_result = unsafe {
245	        RegQueryValueExW(
246	            hkey,
247	            PCWSTR::from_raw(name_wide.as_ptr()),
248	            None,
249	            Some(std::ptr::null_mut()),
250	            None,
251	            Some(&mut data_size),
252	        )
253	    };
254	    if size_result != WIN32_ERROR(0) || data_size == 0 {
255	        tracing::warn!(
256	            value = %value_name,
257	            error_code = size_result.0,
258	            "cloud enforcer: registry value size query failed or empty"
259	        );
260	        return None;
261	    }
262	
263	    // Second call: read the data.
264	    let mut data = vec![0u8; data_size as usize];
265	    let read_result = unsafe {
266	        RegQueryValueExW(
267	            hkey,
268	            PCWSTR::from_raw(name_wide.as_ptr()),
269	            None,
270	            Some(&mut value_type),
271	            Some(data.as_mut_ptr()),
272	            Some(&mut data_size),
273	        )
274	    };
275	    if read_result != WIN32_ERROR(0) {
276	        tracing::warn!(
277	            value = %value_name,
278	            error_code = read_result.0,
279	            "cloud enforcer: registry value read failed"
280	        );
281	        return None;
282	    }
283	    if value_type != REG_SZ && value_type != REG_EXPAND_SZ {
284	        tracing::warn!(
285	            value = %value_name,
286	            type_id = value_type.0,
287	            "cloud enforcer: unexpected registry value type (expected REG_SZ/REG_EXPAND_SZ)"
288	        );
289	        return None;
290	    }
291	
292	    // Data is UTF-16 LE; data_size is in bytes.
293	    let wide: &[u16] = unsafe {
294	        // SAFETY: data buffer holds data_size bytes of valid UTF-16 written by
295	        // RegQueryValueExW.  data_size / 2 gives the u16 count.
296	        std::slice::from_raw_parts(data.as_ptr().cast::<u16>(), (data_size as usize) / 2)
297	    };
298	    Some(
299	        String::from_utf16_lossy(wide)
300	            .trim_end_matches('\0')
301	            .to_string(),
302	    )
303	}
304	
305	/// Enumerates immediate subkey names of an open `HKEY`.
306	///
307	/// Returns an empty `Vec` on failure.
308	#[cfg(windows)]
309	fn enum_subkeys(hkey: HKEY) -> Vec<String> {
310	    let mut names = Vec::new();
311	    // Buffer large enough for a registry key name (max 255 chars + null).
312	    let mut name_buf = vec![0u16; 256];
313	    let mut index = 0u32;
314	    loop {
315	        let mut name_len = name_buf.len() as u32;
316	        let status = unsafe {
317	            RegEnumKeyExW(
318	                hkey,
319	                index,
320	                // lpname: Option<PWSTR>, lpcchname: *mut u32
321	                Some(windows::core::PWSTR::from_raw(name_buf.as_mut_ptr())),
322	                &mut name_len,
323	                None, // lpreserved
324	                None, // lpclass
325	                None, // lpcchclass
326	                None, // lpftlastwritetime
327	            )
328	        };
329	        if status.is_err() {
330	            break;
331	        }
332	        let name = String::from_utf16_lossy(&name_buf[..name_len as usize]).to_string();
333	        names.push(name);
334	        index += 1;
335	    }
336	    names
337	}
