339	// ---------------------------------------------------------------------------
340	// Per-provider resolution
341	// ---------------------------------------------------------------------------
342	
343	/// Probes OneDrive personal and business accounts by enumerating
344	/// `HKEY_USERS\{sid}\SOFTWARE\Microsoft\OneDrive\Accounts` subkeys.
345	#[cfg(windows)]
346	fn resolve_onedrive(sid: &str, out: &mut Vec<SyncPath>) {
347	    let accounts_subkey = r"SOFTWARE\Microsoft\OneDrive\Accounts";
348	    let Some(accounts_key) = open_user_key(sid, accounts_subkey) else {
349	        tracing::info!(
350	            sid = %sid,
351	            "cloud enforcer: OneDrive Accounts key absent — will use fallback"
352	        );
353	        return;
354	    };
355	    let subkeys = enum_subkeys(accounts_key.0);
356	    for account_name in subkeys {
357	        let sub = format!(r"{}\{}", accounts_subkey, account_name);
358	        let Some(acct_key) = open_user_key(sid, &sub) else {
359	            continue;
360	        };
361	        if let Some(raw) = read_reg_string(acct_key.0, "UserFolder") {
362	            if !raw.is_empty() {
363	                tracing::info!(
364	                    sid = %sid,
365	                    account = %account_name,
366	                    path = %raw,
367	                    "cloud enforcer: OneDrive path resolved from registry"
368	                );
369	                out.push(SyncPath {
370	                    provider: CloudProvider::OneDrive,
371	                    path: normalize_path(&raw),
372	                    source: PathSource::Registry,
373	                });
374	            }
375	        }
376	    }
377	}
378	
379	/// Probes Google Drive for Desktop (DriveFS) then legacy Google Drive.
380	#[cfg(windows)]
381	fn resolve_google_drive(sid: &str, out: &mut Vec<SyncPath>) {
382	    // Drive for Desktop (preferred).
383	    let drivefs_key = r"SOFTWARE\Google\DriveFS";
384	    if let Some(key) = open_user_key(sid, drivefs_key) {
385	        if let Some(raw) = read_reg_string(key.0, "DefaultMountPoint") {
386	            if !raw.is_empty() {
387	                tracing::info!(
388	                    sid = %sid, path = %raw,
389	                    "cloud enforcer: Google DriveFS path resolved from registry"
390	                );
391	                out.push(SyncPath {
392	                    provider: CloudProvider::GoogleDrive,
393	                    path: normalize_path(&raw),
394	                    source: PathSource::Registry,
395	                });
396	                return;
397	            }
398	        }
399	    }
400	    // Legacy Google Drive Backup & Sync.
401	    let legacy_key = r"SOFTWARE\Google\Drive";
402	    if let Some(key) = open_user_key(sid, legacy_key) {
403	        if let Some(raw) = read_reg_string(key.0, "Path") {
404	            if !raw.is_empty() {
405	                tracing::info!(
406	                    sid = %sid, path = %raw,
407	                    "cloud enforcer: Google Drive (legacy) path resolved from registry"
408	                );
409	                out.push(SyncPath {
410	                    provider: CloudProvider::GoogleDrive,
411	                    path: normalize_path(&raw),
412	                    source: PathSource::Registry,
413	                });
414	            }
415	        }
416	    }
417	}
