628	impl CloudEnforcer {
629	    /// Constructs a new [`CloudEnforcer`] by calling [`resolve_sync_paths`]
630	    /// with the active console user's SID.
631	    ///
632	    /// Falls back to `%USERPROFILE%`-based defaults when the active user
633	    /// cannot be determined or registry keys are absent.
634	    pub fn new() -> Self {
635	        let sid = active_user_sid();
636	        let sync_paths = resolve_sync_paths(&sid);
637	        tracing::info!(
638	            sid = %sid,
639	            path_count = sync_paths.len(),
640	            "cloud enforcer: sync paths resolved"
641	        );
642	        Self { sync_paths }
643	    }
644	
645	    /// Constructs a new [`CloudEnforcer`] with explicit sync folder prefixes.
646	    ///
647	    /// Each `String` is wrapped as a `SyncPath` with provider `OneDrive` and
648	    /// source `Fallback`.  This preserves backward compatibility with the
649	    /// existing test suite (TC-30..TC-33) which injects raw path strings.
650	    pub fn with_paths(paths: Vec<String>) -> Self {
651	        let sync_paths = paths
652	            .into_iter()
653	            .map(|p| {
654	                let path = normalize_path(&p);
655	                SyncPath {
656	                    provider: CloudProvider::OneDrive,
657	                    path,
658	                    source: PathSource::Fallback,
659	                }
660	            })
661	            .collect();
662	        Self { sync_paths }
663	    }
664	
665	    /// Constructs a [`CloudEnforcer`] with fully typed [`SyncPath`] entries.
666	    ///
667	    /// Used by unit tests that need to exercise provider-specific routing.
668	    pub fn with_sync_paths(sync_paths: Vec<SyncPath>) -> Self {
669	        Self { sync_paths }
670	    }
671	
672	    /// Evaluates whether the given file operation should be blocked based on
673	    /// cloud sync folder policies.
674	    ///
675	    /// Returns `Some(CloudBlockResult)` for T3/T4 write operations inside a
676	    /// sync folder. All other operations return `None` (fall through to ABAC).
677	    ///
678	    /// # Arguments
679	    ///
680	    /// * `path` - Full file path of the operation.
681	    /// * `action` - The [`FileAction`] being evaluated.
682	    /// * `classification` - The ABAC classification resolved by the caller
683	    ///   before invoking this check. The caller is responsible for obtaining
684	    ///   this via `PolicyMapper::provisional_classification` or the live ABAC
685	    ///   evaluator and for logging any resolution failures before falling back
686	    ///   to a safe default (e.g. `Classification::T2`).
687	    ///
688	    /// # Returns
689	    ///
690	    /// - `Some(CloudBlockResult)` — T3/T4 file in sync folder; block.
691	    /// - `None` — not a sync path, or non-sensitive classification; proceed to ABAC.
692	    #[must_use]
693	    pub fn check(
694	        &self,
695	        path: &str,
696	        action: &FileAction,
697	        classification: Classification,
698	    ) -> Option<CloudBlockResult> {
699	        if !is_write_like_action(action) {
700	            return None;
701	        }
702	
703	        let sync_path = self.detect_sync_provider(path)?;
704	        let provider_name = sync_path.provider.display_name().to_string();
705	
706	        // Use the >= operator: T3 and T4 are both sensitive per is_sensitive().
707	        // PartialOrd is derived on Classification (T1 < T2 < T3 < T4).
708	        if classification >= Classification::T3 {
709	            tracing::info!(
710	                path = %path,
711	                provider = %provider_name,
712	                classification = ?classification,
713	                decision = ?Decision::DENY,
714	                "cloud enforcer decision"
715	            );
716	            Some(CloudBlockResult {
717	                decision: Decision::DENY,
718	                reason: format!(
719	                    "Cloud sync blocked: {classification} file in {provider_name} folder"
720	                ),
721	                provider: provider_name,
722	                notify: true,
723	            })
724	        } else {
725	            tracing::trace!(
726	                path = %path,
727	                provider = %provider_name,
728	                classification = ?classification,
729	                decision = ?Decision::ALLOW,
730	                "cloud enforcer decision"
731	            );
732	            None
733	        }
734	    }
735	
736	    /// Returns the [`SyncPath`] whose `path` prefix matches `path`, or `None`.
737	    fn detect_sync_provider(&self, path: &str) -> Option<&SyncPath> {
738	        let lower = path.to_lowercase();
739	        self.sync_paths
740	            .iter()
741	            .find(|sp| lower.starts_with(&sp.path.to_lowercase()))
742	    }
743	}
