749	/// Returns `true` for actions that represent a file being written or created
750	/// in a way that could trigger a cloud upload.
751	fn is_write_like_action(action: &FileAction) -> bool {
752	    matches!(
753	        action,
754	        FileAction::Created { .. } | FileAction::Written { .. } | FileAction::Moved { .. }
755	    )
756	}
