1	//! Hook injector — loads the DLP hook DLL into target processes.
2	//!
3	//! Uses classic DLL injection (`CreateRemoteThread` + `LoadLibraryW`) to
4	//! load `dlp-hook-dll` into sync client processes.  Architecture is checked
5	//! before injection to avoid x64→x86 mismatches.
6	
7	use std::path::PathBuf;
8	
9	use tracing::{debug, info, warn};
10	use windows::core::w;
11	use windows::Win32::Foundation::{CloseHandle, HANDLE, HMODULE, WAIT_OBJECT_0};
12	use windows::Win32::System::Diagnostics::Debug::WriteProcessMemory;
13	use windows::Win32::System::Memory::{
14	    VirtualAllocEx, VirtualFreeEx, MEM_COMMIT, MEM_RELEASE, PAGE_READWRITE,
15	};
16	use windows::Win32::System::ProcessStatus::{EnumProcessModules, GetModuleBaseNameW};
17	use windows::Win32::System::Threading::{
18	    CreateRemoteThread, GetExitCodeThread, IsWow64Process, OpenProcess,
19	    WaitForSingleObject, PROCESS_ACCESS_RIGHTS, PROCESS_ALL_ACCESS,
20	    PROCESS_QUERY_INFORMATION, PROCESS_QUERY_LIMITED_INFORMATION, PROCESS_VM_READ,
21	};
22	
23	/// Errors returned by the hook injector.
24	#[derive(Debug, thiserror::Error)]
25	pub enum HookError {
26	    #[error("target PID {pid} not found or access denied")]
27	    AccessDenied { pid: u32 },
28	
29	    #[error("architecture mismatch: target PID {pid} is {target_arch}, injector is {injector_arch}")]
30	    ArchitectureMismatch {
31	        pid: u32,
32	        target_arch: String,
33	        injector_arch: String,
34	    },
35	
36	    #[error("DLL not found: {path}")]
37	    DllNotFound { path: String },
38	
39	    #[error("DLL path exceeds MAX_PATH (260 chars): {path}")]
40	    PathTooLong { path: String },
41	
42	    #[error("remote memory allocation failed for PID {pid}: {detail}")]
43	    RemoteAllocFailed { pid: u32, detail: String },
44	
45	    #[error("remote write failed for PID {pid}: {detail}")]
46	    RemoteWriteFailed { pid: u32, detail: String },
47	
48	    #[error("remote thread creation failed for PID {pid}: {detail}")]
49	    RemoteThreadFailed { pid: u32, detail: String },
50	
51	    #[error("remote thread did not complete for PID {pid}")]
52	    RemoteThreadTimeout { pid: u32 },
53	
54	    #[error("injection into PID {pid} failed with exit code {exit_code}")]
55	    InjectionFailed { pid: u32, exit_code: u32 },
56	
57	    #[error("process enumeration failed: {0}")]
58	    EnumFailed(String),
59	}
60	
61	/// Injects the DLP hook DLL into a target process.
62	pub struct HookInjector {
63	    /// Path to the x64 hook DLL.
64	    dll_path_x64: PathBuf,
65	    /// Path to the x86 hook DLL (if available).
66	    dll_path_x86: Option<PathBuf>,
67	}
68	
69	impl HookInjector {
70	    /// Creates a new injector with the given DLL paths.
71	    pub fn new(dll_path_x64: impl Into<PathBuf>, dll_path_x86: Option<PathBuf>) -> Self {
72	        Self {
73	            dll_path_x64: dll_path_x64.into(),
74	            dll_path_x86,
75	        }
76	    }
77	
78	    /// Injects the appropriate DLL into the process identified by `pid`.
79	    ///
80	    /// # Errors
81	    ///
82	    /// Returns [`HookError::AccessDenied`] if the process cannot be opened.
83	    /// Returns [`HookError::ArchitectureMismatch`] if the target architecture
84	    /// does not match the available DLL.
85	    /// Returns [`HookError::DllNotFound`] if the DLL file does not exist.
86	    pub fn inject(&self, pid: u32) -> Result<(), HookError> {
87	        info!(pid, "hook injection attempt");
88	
89	        if pid == 0 {
90	            return Err(HookError::AccessDenied { pid });
91	        }
92	
93	        // Determine target architecture.
94	        let target_arch = Self::target_architecture(pid)?;
95	        let injector_arch = Self::current_architecture();
96	
97	        debug!(pid, target_arch, injector_arch, "architecture check");
98	
99	        // Select the correct DLL path.
100	        let dll_path = self.select_dll(target_arch, injector_arch, pid)?;
101	        let dll_path_str = dll_path
102	            .to_str()
103	            .ok_or_else(|| HookError::DllNotFound {
104	                path: dll_path.display().to_string(),
105	            })?;
106	
107	        if dll_path_str.len() > 260 {
108	            return Err(HookError::PathTooLong {
109	                path: dll_path.display().to_string(),
110	            });
111	        }
112	
113	        if !dll_path.exists() {
114	            return Err(HookError::DllNotFound {
115	                path: dll_path.display().to_string(),
116	            });
117	        }
118	
119	        // Open target process.
120	        let process = unsafe {
121	            OpenProcess(PROCESS_ALL_ACCESS, false, pid)
122	                .map_err(|_| HookError::AccessDenied { pid })?
123	        };
124	
125	        let result = self.inject_into_process(process, pid, dll_path_str);
126	
127	        unsafe {
128	            let _ = CloseHandle(process);
129	        }
130	
131	        match &result {
