209	    /// Performs the actual remote-thread injection.
210	    fn inject_into_process(
211	        &self,
212	        process: HANDLE,
213	        pid: u32,
214	        dll_path: &str,
215	    ) -> Result<(), HookError> {
216	        // Encode DLL path as wide string (including null terminator).
217	        let dll_wide: Vec<u16> = dll_path.encode_utf16().chain(std::iter::once(0)).collect();
218	        let dll_bytes = unsafe {
219	            std::slice::from_raw_parts(
220	                dll_wide.as_ptr() as *const u8,
221	                dll_wide.len() * std::mem::size_of::<u16>(),
222	            )
223	        };
224	
225	        // Allocate remote memory for the DLL path.
226	        let remote_mem = unsafe {
227	            VirtualAllocEx(
228	                process,
229	                None,
230	                dll_bytes.len(),
231	                MEM_COMMIT,
232	                PAGE_READWRITE,
233	            )
234	        };
235	
236	        if remote_mem.is_null() {
237	            return Err(HookError::RemoteAllocFailed {
238	                pid,
239	                detail: format!("VirtualAllocEx returned null"),
240	            });
241	        }
242	
243	        // Write DLL path into target process.
244	        let write_result = unsafe {
245	            WriteProcessMemory(
246	                process,
247	                remote_mem,
248	                dll_bytes.as_ptr() as *const std::ffi::c_void,
249	                dll_bytes.len(),
250	                None,
251	            )
252	        };
253	
254	        if let Err(e) = write_result {
255	            unsafe {
256	                let _ = VirtualFreeEx(process, remote_mem, 0, MEM_RELEASE);
257	            }
258	            return Err(HookError::RemoteWriteFailed {
259	                pid,
260	                detail: e.to_string(),
261	            });
262	        }
263	
264	        // Resolve LoadLibraryW address via GetProcAddress so we obtain a
265	        // raw function pointer suitable for CreateRemoteThread.
266	        let load_library_w_addr = unsafe {
267	            let kernel32 = windows::Win32::System::LibraryLoader::GetModuleHandleW(w!("kernel32.dll"))
268	                .map_err(|e| HookError::RemoteThreadFailed {
269	                    pid,
270	                    detail: format!("GetModuleHandleW failed: {}", e),
271	                })?;
272	            let proc = windows::Win32::System::LibraryLoader::GetProcAddress(
273	                kernel32,
274	                windows::core::s!("LoadLibraryW"),
275	            )
276	            .ok_or_else(|| HookError::RemoteThreadFailed {
277	                pid,
278	                detail: "GetProcAddress(LoadLibraryW) returned null".to_string(),
279	            })?;
280	            proc as usize
281	        };
282	
283	        // Create remote thread that calls LoadLibraryW(dll_path).
284	        let thread = unsafe {
285	            CreateRemoteThread(
286	                process,
287	                None,
288	                0,
289	                Some(std::mem::transmute(load_library_w_addr)),
290	                Some(remote_mem),
291	                0,
292	                None,
293	            )
294	            .map_err(|e| HookError::RemoteThreadFailed {
295	                pid,
296	                detail: e.to_string(),
297	            })?
298	        };
299	
300	        // Wait for the remote thread to complete (up to 10 seconds).
301	        let wait_result = unsafe { WaitForSingleObject(thread, 10_000) };
302	
303	        if wait_result != WAIT_OBJECT_0 {
304	            unsafe {
305	                let _ = CloseHandle(thread);
306	                let _ = VirtualFreeEx(process, remote_mem, 0, MEM_RELEASE);
307	            }
308	            return Err(HookError::RemoteThreadTimeout { pid });
309	        }
310	
311	        // Retrieve the thread exit code (module handle on success, 0 on failure).
312	        let mut exit_code: u32 = 0;
313	        unsafe {
314	            GetExitCodeThread(thread, &mut exit_code).map_err(|e| HookError::RemoteThreadFailed {
315	                pid,
316	                detail: e.to_string(),
317	            })?;
318	        }
319	
320	        unsafe {
321	            let _ = CloseHandle(thread);
322	            let _ = VirtualFreeEx(process, remote_mem, 0, MEM_RELEASE);
323	        }
324	
325	        if exit_code == 0 {
326	            return Err(HookError::InjectionFailed { pid, exit_code });
327	        }
328	
329	        debug!(pid, exit_code, "remote LoadLibraryW completed");
330	        Ok(())
331	    }
