333	    /// Returns `true` if the given module name is loaded in the target process.
334	    ///
335	    /// Used by tests to verify injection succeeded.
336	    pub fn is_module_loaded(pid: u32, module_name: &str) -> Result<bool, HookError> {
337	        let process = unsafe {
338	            OpenProcess(
339	                PROCESS_ACCESS_RIGHTS(PROCESS_QUERY_INFORMATION.0 | PROCESS_VM_READ.0),
340	                false,
341	                pid,
342	            )
343	            .map_err(|_| HookError::AccessDenied { pid })?
344	        };
345	
346	        let mut needed: u32 = 0;
347	        let mut modules: [HMODULE; 1024] = [HMODULE(std::ptr::null_mut()); 1024];
348	
349	        let enum_result = unsafe {
350	            EnumProcessModules(
351	                process,
352	                modules.as_mut_ptr(),
353	                (modules.len() * std::mem::size_of::<HMODULE>()) as u32,
354	                &mut needed,
355	            )
356	        };
357	
358	        if enum_result.is_err() {
359	            unsafe {
360	                let _ = CloseHandle(process);
361	            }
362	            return Err(HookError::EnumFailed("EnumProcessModules failed".to_string()));
363	        }
364	
365	        let count = (needed as usize) / std::mem::size_of::<HMODULE>();
366	        let module_names: Vec<String> = modules[..count]
367	            .iter()
368	            .filter_map(|&h| {
369	                if h.0.is_null() {
370	                    return None;
371	                }
372	                let mut buf = [0u16; 260];
373	                let ok = unsafe { GetModuleBaseNameW(process, Some(h), &mut buf) };
374	                if ok == 0 {
375	                    return None;
376	                }
377	                let len = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
378	                Some(String::from_utf16_lossy(&buf[..len]))
379	            })
380	            .collect();
381	
382	        unsafe {
383	            let _ = CloseHandle(process);
384	        }
385	
386	        Ok(module_names
387	            .iter()
388	            .any(|n| n.to_lowercase().contains(&module_name.to_lowercase())))
389	    }
390	}
